(function() {
  'use strict';

  // 教学用简化数据：27 符号（26 字母 + 空格）
  // 零阶：等概
  // 一阶：基于英语频率近似值
  // 二阶：简化双字母转移矩阵（仅展示部分常见组合）
  const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ ';
  const ORDER_0_PROBS = new Array(27).fill(1/27);

  // 一阶近似：英语字母频率（含空格，归一化）
  const ORDER_1_FREQS = [
    0.08, 0.015, 0.03, 0.04, 0.13, 0.02, 0.02, 0.06, 0.07, 0.002, 
    0.008, 0.04, 0.025, 0.07, 0.08, 0.02, 0.001, 0.06, 0.065, 0.09, 
    0.03, 0.01, 0.02, 0.002, 0.02, 0.002, 0.20 // 空格频率最高
  ];
  // 归一化
  const sum1 = ORDER_1_FREQS.reduce((a, b) => a + b, 0);
  const ORDER_1_PROBS = ORDER_1_FREQS.map(p => p / sum1);

  // 二阶近似：简化转移矩阵 (27x27)
  // 仅对部分字母定义转移，其余回退到一阶
  const ORDER_2_TRANS = {};
  // Q 后几乎总是 U
  ORDER_2_TRANS['Q'] = new Array(27).fill(0.01);
  ORDER_2_TRANS['Q']['U'.charCodeAt(0) - 65] = 0.95;
  ORDER_2_TRANS['Q'][26] = 0.04; // 空格
  normalizeProb(ORDER_2_TRANS['Q']);

  // T 后常见 H, S, 空格
  ORDER_2_TRANS['T'] = new Array(27).fill(0.02);
  ORDER_2_TRANS['T']['H'.charCodeAt(0) - 65] = 0.25;
  ORDER_2_TRANS['T']['S'.charCodeAt(0) - 65] = 0.15;
  ORDER_2_TRANS['T'][26] = 0.30;
  normalizeProb(ORDER_2_TRANS['T']);

  // 空格后常见 T, A, O
  ORDER_2_TRANS[' '] = new Array(27).fill(0.03);
  ORDER_2_TRANS[' ']['T'.charCodeAt(0) - 65] = 0.15;
  ORDER_2_TRANS[' ']['A'.charCodeAt(0) - 65] = 0.12;
  ORDER_2_TRANS[' ']['O'.charCodeAt(0) - 65] = 0.10;
  normalizeProb(ORDER_2_TRANS[' ']);

  function normalizeProb(arr) {
    const sum = arr.reduce((a, b) => a + b, 0);
    for (let i = 0; i < arr.length; i++) arr[i] /= sum;
  }

  function calculateEntropy(probs) {
    let H = 0;
    for (let p of probs) {
      if (p > 0) H -= p * Math.log2(p);
    }
    return H;
  }

  function calculateOrder2Entropy(transMatrix) {
    // H = -sum p(i) * sum p(j|i) log p(j|i)
    // 简化：假设 p(i) 为一阶频率
    let H = 0;
    for (let i = 0; i < 27; i++) {
      const pi = ORDER_1_PROBS[i];
      const trans = transMatrix[ALPHABET[i]] || ORDER_1_PROBS;
      let Hi = 0;
      for (let pj of trans) {
        if (pj > 0) Hi -= pj * Math.log2(pj);
      }
      H += pi * Hi;
    }
    return H;
  }

  function generateText(order, length = 100) {
    let text = '';
    let prevChar = ' ';

    for (let i = 0; i < length; i++) {
      let probs;
      if (order === 0) {
        probs = ORDER_0_PROBS;
      } else if (order === 1) {
        probs = ORDER_1_PROBS;
      } else {
        // 二阶：查表，若无定义则回退到一阶
        probs = ORDER_2_TRANS[prevChar] || ORDER_1_PROBS;
      }

      const r = Math.random();
      let cum = 0;
      let idx = 0;
      for (let j = 0; j < probs.length; j++) {
        cum += probs[j];
        if (r <= cum) {
          idx = j;
          break;
        }
      }
      const char = ALPHABET[idx];
      text += char;
      prevChar = char;
    }
    return text;
  }

  // 初始化
  const orderSelect = document.getElementById('order-select');
  const generateBtn = document.getElementById('generate-btn');
  const resetBtn = document.getElementById('reset-btn');
  const textOutput = document.getElementById('text-output');
  const entropyValue = document.getElementById('entropy-value');
  const redundancyValue = document.getElementById('redundancy-value');

  const MAX_ENTROPY = Math.log2(27); // 零阶最大熵

  function updateDisplay() {
    const order = parseInt(orderSelect.value);
    const text = generateText(order);
    textOutput.textContent = text;

    let H;
    if (order === 0) {
      H = calculateEntropy(ORDER_0_PROBS);
    } else if (order === 1) {
      H = calculateEntropy(ORDER_1_PROBS);
    } else {
      H = calculateOrder2Entropy(ORDER_2_TRANS);
    }

    entropyValue.textContent = H.toFixed(2);
    const redundancy = ((MAX_ENTROPY - H) / MAX_ENTROPY * 100).toFixed(1);
    redundancyValue.textContent = redundancy + '%';
  }

  generateBtn.addEventListener('click', updateDisplay);
  resetBtn.addEventListener('click', () => {
    orderSelect.value = '1';
    updateDisplay();
  });
  orderSelect.addEventListener('change', updateDisplay);

  // 初始运行
  updateDisplay();
})();
